$res1 = Invoke-WebRequest -Uri "http://localhost:8080/api/messages" -Method Get; 
$res1.Content;
$res2 = Invoke-WebRequest -Uri "http://localhost:8080/api/messages" -Method Post -ContentType "application/json" -Body '{"user":"Boss", "text":"Hello Voila"}';
$res2.Content;
$res3 = Invoke-WebRequest -Uri "http://localhost:8080/api/messages" -Method Get;
$res3.Content"}|
